// 1. Handle Airtable nested fields structure or direct top-level fields
const inputData = $json.fields || $json;

const jobTitle = (inputData["Job Title"] || inputData.job_title || "").toLowerCase();
const description = (inputData["Job Description"] || inputData.description || "").toLowerCase();
const requiredSkillsStr = inputData["Required Skills"] || inputData.required_skills || "";
const aiRelevance = (inputData["AI Automation Relevance"] || inputData.ai_automation_relevance || "").toLowerCase();
const remoteField = inputData["Remote"] || inputData.remote || false;

// 2. Define your target profile / skills
const targetSkills = [
  "n8n", "ai", "automation", "python", "javascript", 
  "typescript", "api", "apis", "webhook", "webhooks", 
  "claude", "openai", "workflow", "workflows", "llm", "agents"
];

// 3. Parse required skills into an array
let jobSkills = [];
if (Array.isArray(requiredSkillsStr)) {
  jobSkills = requiredSkillsStr;
} else if (typeof requiredSkillsStr === 'string') {
  jobSkills = requiredSkillsStr.split(',').map(s => s.trim()).filter(Boolean);
}

// 4. Calculate skill match score
let matchedSkills = [];
jobSkills.forEach(skill => {
  const cleanSkill = skill.toLowerCase();
  if (targetSkills.some(target => cleanSkill.includes(target))) {
    matchedSkills.push(skill);
  }
});

let skillScore = 0;
if (jobSkills.length > 0) {
  skillScore = Math.round((matchedSkills.length / jobSkills.length) * 100);
} else {
  // Fallback check against description if skills array was empty
  const matchesInDesc = targetSkills.filter(target => description.includes(target));
  skillScore = Math.min(matchesInDesc.length * 20, 100);
}

// 5. Calculate AI Automation Relevance score
let relevanceScore = 50; // default baseline
if (aiRelevance.includes("high") || aiRelevance.includes("tightly coupled") || aiRelevance.includes("core")) {
  relevanceScore = 100;
} else if (aiRelevance.includes("moderate") || aiRelevance.includes("relevant")) {
  relevanceScore = 75;
} else if (aiRelevance.includes("low") || aiRelevance.includes("little")) {
  relevanceScore = 25;
}

// 6. Calculate Remote score
let remoteScore = 50;
if (remoteField === true || description.includes("remote") || description.includes("work from home")) {
  remoteScore = 100;
} else if (description.includes("hybrid")) {
  remoteScore = 50;
} else {
  remoteScore = 0;
}

// 7. Return the enhanced item with calculated scores
return {
  json: {
    ...$json,
    matched_skills: matchedSkills,
    skill_score: skillScore,
    relevance_score: relevanceScore,
    remote_score: remoteScore
  }
};

// 1. Grab scores and text fields from previous nodes (handling Airtable nested fields)
const inputData = $json.fields || $json;
const jobTitle = (inputData["Job Title"] || inputData.job_title || "").toLowerCase();
const experienceReq = (inputData["Experience Required"] || inputData.experience_required || "").toLowerCase();
const description = (inputData["Job Description"] || inputData.description || "").toLowerCase();

const skillScore = $json.skill_score || 0;
const relevanceScore = $json.relevance_score || 0;
const remoteScore = $json.remote_score || 0;

// 2. Check for entry-level friendliness or zero-experience openness
const isEntryLevelFriendly = 
  experienceReq.includes("entry level") || 
  experienceReq.includes("no experience") || 
  experienceReq.includes("zero experience") || 
  experienceReq.includes("fresh graduate") || 
  experienceReq.includes("0-1") || 
  experienceReq.includes("0–1") || 
  experienceReq.includes("trainee") || 
  experienceReq.includes("junior") || 
  description.includes("entry level") ||
  description.includes("no prior experience") ||
  description.includes("training provided");

// 3. Define your weighting matrix (total = 1.0)
const weightSkill = 0.4;       // Gives more weight to your personal tool stack
const weightRelevance = 0.4;
const weightRemote = 0.2;

// 4. Calculate base weighted overall job score (0 to 100)
let overallScore = (skillScore * weightSkill) + 
                   (relevanceScore * weightRelevance) + 
                   (remoteScore * weightRemote);

// 5. Apply an Entry-Level / Zero-Experience Boost (e.g., +15 point bonus)
let entryBoost = 0;
if (isEntryLevelFriendly) {
  entryBoost = 15;
}

// Combine score + boost and cap the maximum at 100
overallScore = Math.min(Math.round(overallScore + entryBoost), 100);

// 6. Return the item with the final score and entry-level flag
return {
  json: {
    ...$json,
    is_entry_level_friendly: isEntryLevelFriendly,
    job_score: overallScore
  }
};

const jobScore = Number($json.job_score || 0);

let recommendation;

if (jobScore >= 81) {
  recommendation = "APPLY";
} else if (jobScore >= 50) {
  recommendation = "CONSIDER";
} else {
  recommendation = "SKIP";
}

return {
  json: {
    ...$json,
    recommendation
  }
};

