});

return items.map(item => {
  // Unpack safely whether it's in body, fields, or root json
  const raw = item.json.body || item.json.fields || item.json;

  // Helper to find a key case-insensitively
  function findKey(obj, targetKey) {
    if (!obj) return '';
    const foundKey = Object.keys(obj).find(k => k.toLowerCase() === targetKey.toLowerCase());
    return foundKey ? obj[foundKey] : '';
  }

  return {
