      description: findKey(raw, 'description') || findKey(raw, 'job description') || 'Example job description used only as a fallback when testing the workflow.'
    }
  };
});

let draftText = "";
let rawOutput = $input.item.json.output;
if (!rawOutput) {
  rawOutput = $input.item.json.text;
}
if (!rawOutput) {
