  try {
    const parsed = JSON.parse(cleanStr);
    draftText = parsed.application_draft || parsed.text || cleanStr;
  } catch (e) {
    draftText = cleanStr;
  }
} else if (typeof rawOutput === 'object' && rawOutput !== null) {
  draftText = rawOutput.application_draft || rawOutput.text || JSON.stringify(rawOutput);
}

return {
